/* Customer workspace. Local demonstration workflows; no external submissions. */
window.SHCustomer=(()=>{
 const pages=['Inspections','Variations','Project documents','Tender scope','Kitset inventory'];
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const id=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
 function init(c){for(const k of ['inspections','variations','documents','tenderScopes','tenderOptions','inventory'])if(!Array.isArray(c.store[k]))c.store[k]=[];c.store.fees??={};}
 const pid=c=>c.projectId||c.project?.id||c.projects?.[0]?.id;
 const rows=(c,k)=>c.store[k].filter(x=>x.projectId===pid(c));
 const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 const area=(name,label,value='')=>`<label>${esc(label)}<textarea name="${name}" rows="3" maxlength="5000">${esc(value)}</textarea></label>`;
 function render(page,c){init(c);if(!pages.includes(page))return '';const project=c.project||c.projects?.find(p=>p.id===pid(c));let body='';
 if(page==='Inspections')body=`<div class="customer-notice"><strong>Check before the next stage</strong><p>Map hold points to the actual building consent and council inspection requirements. The example below is a planning aid, not an approved inspection schedule. A recorded result does not constitute council approval.</p></div><section class="card"><h2>Inspection hold points</h2><p><strong>${rows(c,'inspections').filter(x=>x.status!=='Recorded pass').length} unresolved hold points</strong> · Upcoming dates first</p>${rows(c,'inspections').slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).map(x=>`<article class="customer-item"><h3>${esc(x.name)}</h3><p><strong>Inspection due: ${esc(x.due||'Date not set')}</strong></p><p>Before: <strong>${esc(x.nextStage)}</strong> · Consent reference: ${esc(x.reference||'Not mapped')}</p><span class="tag ${x.status==='Recorded pass'?'':'amber'}">${esc(x.status)}</span><p>Evidence: ${esc(x.evidence||'Awaiting inspection evidence')}</p><details><summary>Record inspection result</summary><form class="customer-form" data-inspection-result="${esc(x.id)}"><label>Recorded result<select name="result"><option value="pending">Pending</option><option value="fail">Fail</option><option value="pass">Pass</option></select></label>${field('inspector','Inspector name')}${field('inspectionDate','Inspection date','','date')}${area('evidence','Evidence reference and result notes')}<p class="small">Local demo record only. A pass requires inspector, date and evidence; it does not verify council approval.</p><button class="primary">Save inspection record</button></form></details></article>`).join('')||'<p>No consent hold points mapped yet. Add the first requirement from your approved consent.</p>'}</section><form class="card customer-form" id="inspectionForm"><h2>Add a consent hold point</h2>${field('name','Inspection requirement (example: pre-pour)', '', 'text','required maxlength="150"')}${field('nextStage','Stage that must wait', '', 'text','required maxlength="150"')}${field('reference','Actual consent / schedule reference', '', 'text','required maxlength="200"')}${field('due','Planned inspection date','','date','required')}<p class="small">This creates a local reminder for all project roles. Stage release remains subject to actual consent conditions and verified evidence.</p><button class="primary">Save hold point & notify</button></form>`;
 if(page==='Variations')body=`<div class="customer-notice"><strong>Changes start with a request</strong><p>Scope, cost and programme changes must be assessed and agreed before work proceeds. Notifications stay in this browser preview.</p></div><form class="card customer-form" id="variationForm"><h2>Request a project variation</h2>${field('title','Change title','','text','required maxlength="150"')}${area('description','Requested scope and reason')}${field('costImpact','Expected cost impact / unknown','','text','required maxlength="200"')}${field('timeImpact','Expected time impact / unknown','','text','required maxlength="200"')}<button class="primary">Send request to project parties</button></form><section class="card"><h2>Variation register</h2>${rows(c,'variations').map(x=>`<article class="customer-item"><h3>${esc(x.title)}</h3><span class="tag amber">${esc(x.status)}</span><p>${esc(x.description)}</p><p>Cost: ${esc(x.costImpact)} · Time: ${esc(x.timeImpact)}</p>${x.assessment?`<p>Assessment: ${esc(x.assessment)}</p>`:''}${x.status==='customer approval'?`<form class="customer-form" data-variation-decision="${esc(x.id)}"><label class="customer-check"><input type="checkbox" name="approvalConfirmed"> I have reviewed the assessed scope, cost and time above and confirm this demo approval. No work starts automatically.</label><div><button class="primary" name="decision" value="approve">Approve assessed scope, cost & time</button><button class="secondary" name="decision" value="reject">Return for assessment</button></div></form>`:'<p class="small">Shed House and the contractor assess the request before customer approval. Approval does not automatically start work.</p>'}</article>`).join('')||'<p>No variation requests for this project.</p>'}</section>`;
 if(page==='Project documents')body=`<section class="card"><h2>Your shared project library</h2><p>Documents added by Shed House appear here when shared with Customer. Check the revision and approval status before using a document for construction.</p>${rows(c,'documents').filter(d=>Array.isArray(d.visibility)&&d.visibility.includes('customer')).map(d=>{let url='';try{const u=new URL(d.url);if(['https:','http:'].includes(u.protocol))url=u.href;}catch{}return `<article class="customer-item"><h3>${esc(d.name)}</h3><p>${esc(d.type)} · Version ${esc(d.version||'Unspecified')} · ${esc(d.status||'Unreviewed')}</p><p class="small">Added ${esc(d.uploadedAt||'Date not recorded')}</p>${d.content?`<details><summary>Read document content</summary><pre class="customer-document-content">${esc(d.content)}</pre><p class="small">${esc(d.status||'Draft')} · Review preparation drafts before use.</p></details>`:''}${url?`<a class="secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open document ↗</a>`:d.content?'':'<span class="small">No valid document link supplied</span>'}</article>`;}).join('')||'<p>No customer documents shared yet. Shed House can add plans, specifications and consent documents to this project.</p>'}</section>`;
 if(page==='Tender scope'){const s=rows(c,'tenderScopes')[0]||{};const fee=c.store.fees.customerTender;body=`<div class="customer-notice"><strong>Define the work before inviting prices</strong><p>A clear scope helps builders price the same package. Confirm consent conditions and responsibilities with your project team.</p></div><form class="card customer-form" id="scopeForm"><h2>Customer → contractor scope</h2><p>Revision ${esc(s.version||0)} · ${esc(s.status||'Draft')}</p>${area('inclusions','Included work',s.inclusions)}${area('exclusions','Excluded work',s.exclusions)}${area('responsibilities','Customer / Shed House / contractor responsibilities',s.responsibilities)}${area('siteAccess','Site access, services and constraints',s.siteAccess)}${area('consentReferences','Consent and inspection references',s.consentReferences)}${area('specification','Specification and drawing revisions',s.specification)}${area('acceptance','Completion and acceptance requirements',s.acceptance)}<label class="customer-check"><input type="checkbox" name="tenderSelected" ${c.store.tenderOptions.some(x=>x.projectId===pid(c)&&x.selected)?'checked':''}> Optional nationwide builder tender service</label><p>${fee==null?'Fee awaiting Shed House configuration. Selection records interest only.':`One-off configured fee: NZD ${Number(fee).toFixed(2)} excl GST; NZD ${(Number(fee)*(1+Number(c.store.fees.gstRate??15)/100)).toFixed(2)} incl ${esc(c.store.fees.gstRate??15)}% GST.`} No payment is taken.</p><label class="customer-check"><input type="checkbox" name="confirm" required> I have reviewed these scope requirements for tender preparation.</label><button class="primary">Save scope revision</button></form>`;}
 if(page==='Kitset inventory'){const items=rows(c,'inventory').filter(x=>Array.isArray(x.visibility)&&x.visibility.includes('customer'));const groups=[...new Set(items.map(x=>x.category||'Uncategorised'))];body='<div class="customer-notice"><strong>Your kitset, section by section</strong><p>Shared by Shed House for planning and delivery checks. Confirm quantities and specifications against approved engineering and supplier schedules before construction.</p></div>'+groups.map(cat=>'<section class="card"><h2>'+esc(cat)+'</h2><div class="table-wrap"><table><thead><tr><th>Component / specification</th><th>Quantity</th><th>Supply status</th></tr></thead><tbody>'+items.filter(x=>(x.category||'Uncategorised')===cat).map(x=>'<tr data-inventory-row="'+esc(x.id)+'"><td><strong>'+esc(x.name)+'</strong>'+esc(x.spec||'Specification pending')+'</td><td>'+esc(x.qty)+' '+esc(x.unit)+'</td><td>'+esc(x.status||'Not recorded')+'</td></tr>').join('')+'</tbody></table></div></section>').join('');if(!groups.length)body+='<section class="card"><h2>Inventory awaiting Shed House</h2><p>No kitset items have been shared with this customer yet.</p></section>';}
 return `<div class="customer-workspace"><div class="heading"><div><div class="eyebrow">CUSTOMER WORKSPACE · LOCAL DEMO</div><h1>${esc(page)}</h1><p>${esc(project?.name||'Your project')} · ${esc(pid(c)||'No project selected')}</p></div></div>${body}</div>`;}
 function bind(page,c){init(c);const save=()=>{c.save();c.navigate(page);};const notify=(title,message,kind)=>c.notify({title,message,roles:['staff','customer','contractor'],projectId:pid(c),kind});
 const form=document.getElementById('inspectionForm');if(form)form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));c.store.inspections.push({...f,id:id(),projectId:pid(c),status:'Hold — inspection required',createdAt:new Date().toISOString()});notify('Inspection hold point added',`${f.name} is required before ${f.nextStage}. Planned ${f.due}; confirm booking with the council.`,'inspection');save();};
 document.querySelectorAll('[data-inspection-result]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const x=rows(c,'inspections').find(v=>v.id===form.dataset.inspectionResult);if(!x)return;const f=Object.fromEntries(new FormData(form));if(f.result==='pass'&&(!f.inspector.trim()||!f.inspectionDate||!f.evidence.trim()))return c.toast('A recorded pass requires inspector, date and evidence');x.status=f.result==='pass'?'Recorded pass':f.result==='fail'?'Hold — recorded fail':'Hold — pending';x.evidence=f.evidence;x.inspector=f.inspector;x.inspectionDate=f.inspectionDate;x.recordedAt=new Date().toISOString();notify('Inspection result recorded',x.name+': '+x.status+'. Verify consent requirements before continuing.','inspection');save();});
 const variation=document.getElementById('variationForm');if(variation)variation.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(variation));if(!f.description.trim())return c.toast('Describe the requested scope');c.store.variations.push({...f,id:id(),projectId:pid(c),status:'requested',createdAt:new Date().toISOString(),requestedBy:'customer'});notify('Customer variation requested',`${f.title}: scope, cost and time assessment required before work.`,'variation');save();};
 document.querySelectorAll('[data-variation-decision]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const x=rows(c,'variations').find(v=>v.id===form.dataset.variationDecision);if(!x||x.status!=='customer approval')return;const approving=e.submitter?.value==='approve';if(approving&&!new FormData(form).has('approvalConfirmed'))return c.toast('Confirm you have reviewed the scope, cost and time before demo approval');x.status=approving?'approved work':'assessment';x.customerDecisionAt=new Date().toISOString();if(!Array.isArray(x.history))x.history=[];x.history.push({at:x.customerDecisionAt,by:'customer',status:x.status});notify('Variation decision recorded',x.title+': '+x.status+'. Project parties must coordinate the agreed next step.','variation');save();});
 const scope=document.getElementById('scopeForm');if(scope)scope.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(scope));const old=rows(c,'tenderScopes')[0];const data={...f,id:old?.id||id(),projectId:pid(c),version:(Number(old?.version)||0)+1,status:'Customer reviewed',updatedAt:new Date().toISOString()};if(old)Object.assign(old,data);else c.store.tenderScopes.push(data);let option=rows(c,'tenderOptions')[0];if(!option){option={id:id(),projectId:pid(c)};c.store.tenderOptions.push(option);}Object.assign(option,{selected:f.tenderSelected==='on',feeSnapshot:c.store.fees.customerTender??null,gstRateSnapshot:c.store.fees.gstRate??15,feeExclGst:c.store.fees.customerTender??null,feeInclGst:c.store.fees.customerTender==null?null:Number(c.store.fees.customerTender)*(1+Number(c.store.fees.gstRate??15)/100),status:'Interest only — no payment',updatedAt:data.updatedAt});notify('Tender scope revised',`Customer scope revision ${data.version} saved. Review changes before tender issue.`,'scope');save();};
 }
 return {pages,render,bind};
})();
